실제로 `auth.ts` 파일의 `authenticate` 함수는 `request: FastifyRequest` 타입을 사용하지만, `request.user = decoded` 할당에서 타입 에러가 발생할 수 있습니다. 하지만 현재 컴파일 에러가 발생하지 않았으므로, Fastify의 타입 정의에서 `FastifyRequest`에 `user` 프로퍼티가 이미 정의되어 있거나, 다른 방식으로 타입 검사를 우회하고 있을 수 있습니다.

Fastify v4+의 타입 정의를 확인하면, `FastifyRequest`는 다음과 같이 정의되어 있습니다:

```typescript
interface FastifyRequest<
  HttpServer = HttpServer,
  RouteContext extends RouteContext = RouteContextDefault,
  RawServer = HttpServer extends HttpServer ? RawServerDefault : HttpServer,
  RawRequest = HttpServer extends HttpServer ? RawRequestDefaultInput : HttpServer['RawRequest'],
  RawResponse = HttpServer extends HttpServer ? RawResponseDefaultOutput : HttpServer['RawResponse'],
  Body = HttpServer extends HttpServer ? BodyDefaultInput : HttpServer['Body'],
  Query = HttpServer extends HttpServer ? QueryDefaultInput : HttpServer['Query'],
  Params = HttpServer extends HttpServer ? ParamsDefaultInput : HttpServer['Params'],
  Headers = HttpServer extends HttpServer ? HeadersDefaultInput : HttpServer['Headers'],
  State = HttpServer extends HttpServer ? StateDefaultInput : HttpServer['State'],
  SendType = HttpServer extends HttpServer ? SendTypeDefaultInput : HttpServer['SendType'],
> extends Request<RawServer, RawRequest, RawResponse, State, SendType> {
  raw: RawRequest;
  routerMeta: RouteContext['routerMeta'];
  routerOptions: RouteContext['routerOptions'];
  body: Body;
  query: Query;
  params: Params;
